"use strict";(self.webpackChunkdocs_scadys_io=self.webpackChunkdocs_scadys_io||[]).push([["6702"],{552(e,t,a){a.r(t),a.d(t,{metadata:()=>n,default:()=>c,frontMatter:()=>i,contentTitle:()=>o,toc:()=>h,assets:()=>d});var n=JSON.parse('{"id":"bring-up/fault-finding/case-studies","title":"Case Studies","description":"These cases come from the bring-up of two Scadys prototypes. In both, a failed part was suspected first, and in both, the real faults were in the assembly or in the expected value.","source":"@site/engineering/bring-up/fault-finding/case-studies.md","sourceDirName":"bring-up/fault-finding","slug":"/bring-up/fault-finding/case-studies","permalink":"/engineering/bring-up/fault-finding/case-studies","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":5,"frontMatter":{"sidebar_position":5,"title":"Case Studies"},"sidebar":"aboutSidebar","previous":{"title":"Measurement Traps","permalink":"/engineering/bring-up/fault-finding/measurement-traps"},"next":{"title":"Recording results","permalink":"/engineering/bring-up/recording-results"}}'),r=a(4848),s=a(8453);let i={sidebar_position:5,title:"Case Studies"},o="Case Studies",d={},h=[{value:"MDD500 V0.1, board 1",id:"mdd500-v01-board-1",level:2},{value:"Bridges from the paste print",id:"bridges-from-the-paste-print",level:3},{value:"Open joints after a paste-free re-seat",id:"open-joints-after-a-paste-free-re-seat",level:3},{value:"A good processor replaced on a wrong expectation",id:"a-good-processor-replaced-on-a-wrong-expectation",level:3},{value:"Backwards ESD diodes",id:"backwards-esd-diodes",level:3},{value:"An open joint on the sensor bus",id:"an-open-joint-on-the-sensor-bus",level:3},{value:"What the board taught",id:"what-the-board-taught",level:3},{value:"MDD400 V2.9, board 1",id:"mdd400-v29-board-1",level:2},{value:"A transmit line stuck near 1 V",id:"a-transmit-line-stuck-near-1-v",level:3},{value:"The cause was the footprint",id:"the-cause-was-the-footprint",level:3},{value:"What the board taught",id:"what-the-board-taught-1",level:3}];function l(e){let t={h1:"h1",h2:"h2",h3:"h3",header:"header",li:"li",p:"p",ul:"ul",...(0,s.R)(),...e.components};return(0,r.jsxs)(r.Fragment,{children:[(0,r.jsx)(t.header,{children:(0,r.jsx)(t.h1,{id:"case-studies",children:"Case Studies"})}),"\n",(0,r.jsx)(t.p,{children:"These cases come from the bring-up of two Scadys prototypes. In both, a failed part was suspected first, and in both, the real faults were in the assembly or in the expected value."}),"\n",(0,r.jsx)(t.h2,{id:"mdd500-v01-board-1",children:"MDD500 V0.1, board 1"}),"\n",(0,r.jsx)(t.p,{children:"The first MDD500 board was assembled by hand in October 2026. It has an ESP32-P4 processor, U4, in a 0.35 mm pitch QFN104 package, on a board populated on both faces."}),"\n",(0,r.jsx)(t.h3,{id:"bridges-from-the-paste-print",children:"Bridges from the paste print"}),"\n",(0,r.jsx)(t.p,{children:"The top face was printed through a 0.10 mm stencil with full paste on U4, and placement took about eight hours. After reflow, U4 showed many solder bridges, at least eight of them, including one between the flash clock and data pins that read through on the flash chip. The power monitor, U11, was bridged as well."}),"\n",(0,r.jsx)(t.p,{children:"The board's mask dams were present and correct, so the bridges came from the paste print. The paste was spread with a stiff plastic card pressed down onto the stencil, which forced paste under the stencil and around the apertures. U11 was reworked the same day."}),"\n",(0,r.jsx)(t.p,{children:"The bottom face was later printed with a thick coated paper card, held vertical and swiped horizontally, and its 40-pin connector and two small sensors reflowed correctly first time."}),"\n",(0,r.jsx)(t.h3,{id:"open-joints-after-a-paste-free-re-seat",children:"Open joints after a paste-free re-seat"}),"\n",(0,r.jsx)(t.p,{children:"U4 and the radio module were lifted, cleaned and re-seated on flux alone, with no fresh paste. At first power the board drew 38 mA, the UART pins read 0 V, and several of the processor's internal rails read near zero. In diode mode, both UART pins read open circuit to ground. Under the microscope, many of U4's edge pins were not touching their pads, because the package sat proud. Re-soldering one side with a needle iron and a little paste brought both UART pins to a 0.51 V diode drop, and all four sides were then re-soldered."}),"\n",(0,r.jsx)(t.h3,{id:"a-good-processor-replaced-on-a-wrong-expectation",children:"A good processor replaced on a wrong expectation"}),"\n",(0,r.jsx)(t.p,{children:"With every joint confirmed, the processor's core rail still read millivolts, against the bring-up sheet's expectation of about 1.1 V. A written fault-finding process ran to its end, and its readings were taken as a core domain open inside the package. U4 was replaced with a second chip, using hot air to lift it, hand-applied paste because the stencil could not lie on the populated board, and the hot plate to reflow it."}),"\n",(0,r.jsx)(t.p,{children:"The new chip gave the same readings. A serial adapter on the processor's UART then captured the ROM boot log at 115200 baud. It showed the ROM running, reading an all-ones header from a blank flash, and resetting on its watchdog every few hundred milliseconds. That is a healthy processor with nothing to run. The core rail reads millivolts on a blank ESP32-P4 because the processor powers it only when firmware enables the external converter. The bring-up sheet's expected value was wrong. The first chip, removed on the strength of that expectation, is unproven rather than dead."}),"\n",(0,r.jsx)(t.h3,{id:"backwards-esd-diodes",children:"Backwards ESD diodes"}),"\n",(0,r.jsx)(t.p,{children:"The board did not appear as a USB device. D+ sat at 0.81 V and D- at 0 V. With the board unpowered, the meter in diode mode, the red lead on each USB line and the black lead on ground, both lines read 0.767 V, a forward diode drop to ground. The two ESD diodes, D1 and D2, were fitted backwards. Their mark identifies pin 1, which is ground, and they had been placed with the mark at the USB end, where habit puts a cathode band. The footprint was correct."}),"\n",(0,r.jsx)(t.p,{children:"Their orientation had been argued from the datasheet during placement. A meter in diode mode across one diode before placing it would have settled the question in a minute, and saved a day of fault-finding and rework. With both turned round, the board enumerated as a USB Serial/JTAG device on the next power-up."}),"\n",(0,r.jsx)(t.h3,{id:"an-open-joint-on-the-sensor-bus",children:"An open joint on the sensor bus"}),"\n",(0,r.jsx)(t.p,{children:"The bring-up app then found no devices on its first I\xb2C bus. Unpowered, both bus lines read their pull-ups into the 3.3 V rail, but the processor's data pin read open from its flank to the pull-up's pad. A touch with the needle iron fixed it, and the next scan found all three sensors."}),"\n",(0,r.jsx)(t.h3,{id:"what-the-board-taught",children:"What the board taught"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsx)(t.li,{children:"Every fault on the board was an assembly fault. There were bridges, open joints and two parts fitted backwards."}),"\n",(0,r.jsx)(t.li,{children:"The one apparent part failure was a wrong expected value, and it cost a processor."}),"\n",(0,r.jsx)(t.li,{children:"The ROM boot log is the cheapest proof that a blank processor is alive, and it belongs in first power."}),"\n",(0,r.jsx)(t.li,{children:"The next build prints paste with a paper card, keeps the time from print to reflow short and measures any part whose orientation is in doubt before placing it, with the bridge sweep and orientation checks before first power."}),"\n"]}),"\n",(0,r.jsx)(t.h2,{id:"mdd400-v29-board-1",children:"MDD400 V2.9, board 1"}),"\n",(0,r.jsx)(t.p,{children:"The MDD400 V2.9 board drives its Legacy Serial Protocol line through small dual transistors in SOT-363 packages."}),"\n",(0,r.jsx)(t.h3,{id:"a-transmit-line-stuck-near-1-v",children:"A transmit line stuck near 1 V"}),"\n",(0,r.jsx)(t.p,{children:"The legacy serial transmitter did not work. The line sat clamped at about 1.08 V. In-circuit voltages pointed into the driver stage: one transistor's base was off, yet its collector sat at 0.80 V. That looked like leakage inside the transistor."}),"\n",(0,r.jsx)(t.p,{children:"Before any part was removed, the board was powered down and each adjacent pin pair of the driver transistors was read for continuity. Two pairs were shorted, pins 2 and 3 of Q11 and pins 2 and 3 of Q8, and the microscope confirmed solder bridges on both. The Q11 bridge tied one transistor's base to its partner's collector, so the base-emitter junction clamped the line at one diode drop. The Q8 bridge was hidden behind the Q11 fault until both were cleared. Flux, a fine-tip iron, wick and hot air cleared them, the retest passed, and no part was replaced."}),"\n",(0,r.jsx)(t.h3,{id:"the-cause-was-the-footprint",children:"The cause was the footprint"}),"\n",(0,r.jsx)(t.p,{children:"The bridges had a cause beyond assembly. The SOT-363 footprint in the library carried one merged solder-mask opening across each row of three pins, so there was no mask dam between them. The same defect caused bridges on a WTI400 board and on other footprints, including a display flat-flex connector and a temperature sensor. The library was corrected so that every pair of pads keeps a mask dam at least as wide as the fabricator's minimum. The same audit found the ESP32-P4 footprint's dam was half the minimum, and corrected it before the MDD500 was ordered."}),"\n",(0,r.jsx)(t.h3,{id:"what-the-board-taught-1",children:"What the board taught"}),"\n",(0,r.jsxs)(t.ul,{children:["\n",(0,r.jsx)(t.li,{children:"An in-circuit reading that suggests a failed part is confirmed with the board unpowered before the part is removed. Inspecting first saved a good transistor."}),"\n",(0,r.jsx)(t.li,{children:"A bridge that recurs at the same pins on more than one board points to the footprint, not the assembler."}),"\n"]})]})}function c(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,r.jsx)(t,{...e,children:(0,r.jsx)(l,{...e})}):l(e)}},8453(e,t,a){a.d(t,{R:()=>i,x:()=>o});var n=a(6540);let r={},s=n.createContext(r);function i(e){let t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(r):e.components||r:i(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);